"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[684],{109:(e,a,n)=>{n.d(a,{A:()=>t});let t=(0,n(4294).A)("Search",[["circle",{cx:"11",cy:"11",r:"8",key:"4ej97u"}],["path",{d:"m21 21-4.3-4.3",key:"1qie3q"}]])},9846:(e,a,n)=>{n.d(a,{D:()=>t});let t=[{id:"chicken-pickin-roll",name:"Chicken Pickin' Roll en G",category:"chicken-pickin",description:"El t\xedpic roll de quinta palm-mute sobre les cordes B i G, amb la nota alta que rellisca avall fins a la t\xf2nica. \xc9s la base del so sec i saltironat de Brent Mason: cinquena que balla cap a la resoluci\xf3 amb atac de pua sec.",tab:"e|-----------------------------------8-|\nB|--8-8-8-8-8-8-8-8-8-8-8-8-8-8-8-8---|\nG|--7-7-7-7-7-7-7-7-7-7-7-7-7-7-7-7---|\nD|------------------------------------|\nA|------------------------------------|\nE|------------------------------------|",key:"G",difficulty:"advanced",artists:["Brent Mason","Brad Paisley","Johnny Hiland"],tips:["B(8) i G(7) s\xf3n la quintena (D-G); deixa que sonin juntes sota palm mute lleuger, nom\xe9s per esmorteir.","Alterna pua estricta (D U D U) a 16ens; la velocitat surt del canell, no del bra\xe7.",'Acaba en la G aguda (E, 8\xe8 traste) per resoldre a la t\xf2nica amb un "pop" de pua.']},{id:"banjo-roll-en-g",name:"Banjo Roll en G",category:"banjo-roll",description:"Adaptaci\xf3 del forward roll del banjo de 5 cordes a la guitarra: el baix alterna t\xf2nica i quinta a la corda D mentre el discant desfila 3-2-1, recordant la corda aguda del banjo. La repetici\xf3 en travessa de cordes \xc9S el roll, no farcit.",tab:"e|-------------------------------3-3-3--|\nB|-----------------3----3----3----3-3-3--|\nG|-----------2----2----2----2-----------|\nD|---0-5---0-5---0-5---0-5---0-5--------|\nA|-3---------3----3----3----3-----------|\nE|--------------------------------------|",key:"G",difficulty:"intermediate",artists:["Don Rich","Albert Lee","Redd Volkaert"],tips:["El polze marca constant (0-5 / 3) al baix; els dits fan la travessa de cordes agudes com si fos el banjo.","Pica amb pua alternada estricta i deixa ressonar les cordes a l'aire per l'efecte dron.","El D(5ta) sota el G(0) crea la quinta; mant\xe9n-lo estable mentre el discant es mou."]},{id:"double-stop-shuffle",name:"Double Stop Shuffle",category:"double-stop",description:"Shuffle amb dobles terceres i sisenes sobre C-G: la parella de notes puja i baixa per graus amb swing llarga-curta, com el so ple i ballable del country de Nashville. Cada doble parada \xe9s una tercera que sona contra el baix.",tab:"e|-----------8----------------7--------|\nB|--------8-----8----------7-----7-----|\nG|------7-----------7----8---------8---|\nD|---10-----------10---9---------------|\nA|------------------------------------|\nE|------------------------------------|",key:"C",difficulty:"intermediate",artists:["Chet Atkins","James Burton","Don Rich"],tips:["Toca les parelles amb un moviment de canell \xfanic i swing llarga-curta (l'est\xe0ndard del shufflle honky-tonk).","La primera doble parada (D10/G7 o G8/B8) \xe9s la tercera i quinta de C; la segona resolt sobre el G.","Mant\xe9n els dos dits a la mateixa forma mentre canvieu de traste per no trencar el doble."]},{id:"pedal-steel-bend",name:"Pedal Steel Bend",category:"bend",description:"Bend d'un to sostingut que imita el lliscament del pedal steel, amb vibrato ample mentre sona. La nota de dest\xed (F# sobre E) \xe9s la tercera major, la nota country per excel\xb7l\xe8ncia: s'hi arriba lliscant des de la segona (E) amb control.",tab:"e|--7b9--------7b9--------7b9-----7~|\nB|---------------------------------|\nG|---------------------------------|\nD|---------------------------------|\nA|---------------------------------|\nE|---------------------------------|",key:"E",difficulty:"intermediate",artists:["Albert Lee","Redd Volkaert","Danny Gatton"],tips:["El bend de B(7 a 9) puja amb el canell girant-lo, no amb la for\xe7a del dit; el dit \xedndex refor\xe7a el mig.","Mant\xe9n el vibrato AMB bend actiu movent tot el canell sense rebaixar la nota.","El to s'aconsegueix pujant fins que soni exactament com el F# pisat (cordes D/E); comprova-ho amb la nota real."]},{id:"open-string-g-lick",name:"Open String G Lick",category:"open-string",description:"Lick que aprofita el dron de la corda G a l'aire sota una frase de B i E, amb final a la t\xf2nica. La corda lliure ressona de fons i dona el so brillant i obert del country cl\xe0ssic; la melodia puja i torna a caure a la G.",tab:"e|---------------------------------------|\nB|-----3--0-----3--0-----3--0-----3--0---|\nG|--0--------0--------0--------0---------|\nD|---------------------------------------|\nA|-----------------------------4--2--3---|\nE|---------------------------------------|",key:"G",difficulty:"beginner",artists:["Don Rich","Chet Atkins","James Burton"],tips:["La G a l'aire (corda 3) drona sota les notes de la B; deixa-la ressonar, no l'apaguis.","Alterna pua i dit perqu\xe8 la frase flueixi com un cant.","Acaba a D(4) C(2) G(3) a la corda A per resoldre clarament a la t\xf2nica."]},{id:"travis-picking-pattern",name:"Travis Picking Pattern",category:"travis-picking",description:"El patr\xf3 de Travis de veritat: el polze alterna constantment entre la t\xf2nica i la quinta (E i A) mentre el dit mig i l'\xedndex toquen la melodia a les cordes agudes. Tota la gr\xe0cia \xe9s el baix alternat que NO para mai.",tab:"e|-----------------------------|\nB|--3--3--3--3--3--3--3--3--3--|\nG|--0-----0-----0-----0-----0--|\nD|-----------------------------|\nA|--5-----5-----5-----5-----5--|\nE|--3-----3-----3-----3-----3--|",key:"G",difficulty:"intermediate",artists:["Merle Travis","Chet Atkins","Jerry Reed"],tips:["El polze ALTERNA sempre T\xf2nica (E-3) amb Quinta (A-5); no el deixis clavat a una sola corda o no \xe9s Travis.","L'\xedndex toca el G(0) i el mig el D(3, corda B) de manera independent del polze.","Comen\xe7a nom\xe9s amb el baix alternant E-3 / A-5 fins a interioritzar-lo, despr\xe9s afegeix els dits."]},{id:"crosspicking-arpeggio",name:"Crosspicking Arpeggio",category:"crosspicking",description:'Arpegi de G amb patr\xf3 de pua creuat (D-U-D-M o D-U-D) sobre tres cordes, com el roll de banjo per\xf2 amb pua plana. El canvi de corda \xe9s constant i el moviment del canell fa el "flaix" dens caracter\xedstic del bluegrass.',tab:"e|-----------------------------5--7--8--7--5--|\nB|------------------3--5--7--8-----------------|\nG|-------0--2--4--5----------------------------|\nD|----0--5-------------------------------------|\nA|---------------------------------------------|\nE|---------------------------------------------|",key:"G",difficulty:"advanced",artists:["Don Rich","Albert Lee","Johnny Hiland"],tips:["Pica amb patr\xf3 creuat constant (D-U-D-U) i deixa que la pua \"reboti\" d'una corda a l'altra.","\xc9s un arpegi de G amb la s\xe8tima (F#) de pas cap al D i de tornada a la t\xf2nica.","Practica cada travessa de corda a\xefllada abans d'unir les tres; la velocitat ve de la regularitat del canell."]},{id:"flatpicking-g-run",name:"Flatpicking G-Run",category:"flatpicking",description:'La baixada de G per graus que connecta acords: de la s\xe8tima (F#) baixant crom\xe0tic fins a la t\xf2nica amb pua alternada. \xc9s el "turnaround" essencial del bluegrass, i cada grau toca el corresponent de l\'acord de dest\xed.',tab:"e|----------------------------3--5--7--8--7--|\nB|----------------------3--6-----------------|\nG|--------------0--2--5----------------------|\nD|--------0--2--4----------------------------|\nA|--0--3--5----------------------------------|\nE|-------------------------------------------|",key:"G",difficulty:"intermediate",artists:["Don Rich","Redd Volkaert","Albert Lee"],tips:["Pica alternada estricta i deixa que les notes s'encadenin com un roll, sense picar-les marcades a\xefllades.","El D(5\xe8, corda A) \xe9s la quinta; el C(3\xe8) la quarta; el B(2\xe8) la tercera — els graus de l'acord de G.","Pratca la baixada i la tornada per separat fins que el canvi de corda sigui invisible."]},{id:"hybrid-picking-arpeggio",name:"Hybrid Picking Arpeggio",category:"hybrid-picking",description:"Arpegi de G amb hybrid picking: la pua ataca les cordes greus i els dits (\xedndex, mig, anular) les agudes, permetent salts grans entre cordes sense moure massa la m\xe0. \xc9s el so t\xe8cnic i n\xedtid del country modern de Brent Mason.",tab:"e|--------------------------15--17--12--15--|\nB|-----------------12--15--------------------|\nG|--------10--12-----------------------------|\nD|-------12----------------------------------|\nA|--10--12----------------------------------|\nE|-------------------------------------------|",key:"G",difficulty:"advanced",artists:["Brent Mason","Brad Paisley","Johnny Hiland"],tips:["Pua per les cordes greus (A, D) i dit \xedndex/mig/anular per les agudes; el canvi de corda \xe9s immediat.","\xc9s un arpegi de G major que salta octaves: G-D-G-B-G-D-G-E-D.","Mant\xe9n la m\xe0 quieta i fes els salts amb els DITS, no amb el canell, per anar r\xe0pid i net."]},{id:"string-bend-release",name:"String Bend + Release",category:"bend",description:'Bend i alliberament amb un to per sota: puja a la tercera des de la segona i torna a caure, creant un so vocal i expressiu. El "release" \xe9s el gest m\xe9s cantable del country; el bend arriba net i la tornada \xe9s controlada.',tab:"e|--7b9-7b9--9---9b11-9---9b11-9---9b11--|\nB|-----------------------------------------|\nG|-----------------------------------------|\nD|-----------------------------------------|\nA|-----------------------------------------|\nE|-----------------------------------------|",key:"E",difficulty:"intermediate",artists:["Danny Gatton","Albert Lee","Redd Volkaert"],tips:["Puja el bend amb el canell i TORNA a baixar amb el mateix dit sense soltar la corda.","Controla la velocitat del release — la baixada lenta \xe9s el que sona com a cant; la r\xe0pida com a slap.","Vibra lleugerament al cim del bend (9b11) abans d'alliberar."]},{id:"palm-mute-chicken-pickin",name:"Palm Mute Chicken Pickin'",category:"chicken-pickin",description:"Chicken pickin' amb atac de pua accentuat i escapada a la corda a l'aire: la nota \"click\" del palm mute seguida d'una nota oberta que ressona. \xc9s la seq\xfc\xe8ncia seca-pop que defineix el so de Brad Paisley.",tab:"e|------------------------------------|\nB|--------------8----------8----------|\nG|--7pm--7pm--7----7pm--7----7pm--7---|\nD|--7pm--7pm--7----7pm--7----7pm--7---|\nA|------------------------------------|\nE|------------------------------------|",key:"G",difficulty:"advanced",artists:["Brent Mason","Brad Paisley","Johnny Hiland"],tips:['El palm mute ha de ser lleuger (esmorteir, no silenciar) i cada nota atacada amb un "pop" de pua.','Alterna 7pm amb les notes obertes a l\'aire perqu\xe8 el so "pup" i ressoni.',"El D(7) doblat a les cordes G i D dona la quinta; la nota oberta seg\xfcent \xe9s la que sona neta."]},{id:"fingerpicking-pattern",name:"Fingerpicking Pattern",category:"fingerpicking",description:"Patr\xf3 de fingerpicking amb el baix independent: el polze toca t\xf2nica-quinta (E i A) mentre l'\xedndex i el mig fan la melodia als aguts, tots tres en moviment constant. \xc9s l'estil Chet Atkins: el baix no sembla parar mai.",tab:"e|--3--------------------3-----------|\nB|--0--3--0--3--0--3--0--3-----------|\nG|--0-----0-----0-----0--------------|\nD|-----------------------------------|\nA|--5-----5-----5-----5-------------|\nE|--3-----3-----3-----3-------------|",key:"G",difficulty:"beginner",artists:["Chet Atkins","Merle Travis","Jerry Reed"],tips:["L'\xedndex toca el G(0), el mig alterna E(3) i D(3, corda B), i el polze alterna E-3 / A-5.","Mant\xe9n el ritme del polze absolutament constant, com un metr\xf2nom, perqu\xe8 suporti tota la melodia.","Practica lent\xedssim i augmenta la velocitat nom\xe9s quan el polze no tingui ni una pausa."]},{id:"double-stop-slide",name:"Double Stop Slide",category:"double-stop",description:"Dobles terceres que llisquen avall i pugen resoltant sobre l'acord, amb el so suau del western swing de Don Rich. La doble parada sona primer sobre el marge alt i llisca fins al traste de dest\xed, expressiu i net.",tab:"e|-----------------8--7--------|\nB|-----------8--10--8--7--10----|\nG|--------7--7-----------------|\nD|-----10--9-------------------|\nA|-----------------------------|\nE|-----------------------------|",key:"C",difficulty:"intermediate",artists:["Don Rich","Chet Atkins","James Burton"],tips:["Llisca les dues cordes JUNTES amb la mateixa pressi\xf3 per no trencar la tercera.","La doble parada de C (D10/G7/E8/B8) \xe9s tercera i quinta; la segona (D9/G7/E8/B10) resolt sobre el G.","Afegeix un vibrato suau just abans d'arribar al traste de dest\xed."]},{id:"open-e-lick",name:"Open E Lick",category:"open-string",description:"Lick rockabilly/country sobre el dron de la corda E a l'aire: la melodia puja per la corda B i el dron ressona de fons, creant l'efecte de pedal steel obert. La segona i la tercera es resolen contra el dron greu.",tab:"e|---------------------------------|\nB|--2--4--2--0----------------------|\nG|-----------------1--0-------------|\nD|----------------------------------|\nA|----------------------------------|\nE|--0--0--0--0---0--0--0--0--------|",key:"E",difficulty:"beginner",artists:["James Burton","Don Rich","Danny Gatton"],tips:["El dron de la corda E a l'aire sona sempre de fons; no l'apaguis mentre toques el B(2) i F#(4).","Alterna pua i dit i deixa que les notes agudes ressonin contra el baix obert.","\xc9s la tercera (G#, corda G 1) i segona (F#, corda G 2) que es resolen sobre el dron greu."]},{id:"bluegrass-g-run",name:"Bluegrass G-Run (Amunt)",category:"flatpicking",description:"La pujada de G crom\xe0tica i per graus que connecta dos acords a l'inrev\xe9s: puja des de la t\xf2nica fins a la tercera passant per la segona, per la quinta i per la s\xe8tima. Complement del G-Run avall, tots dos indispensables al turnaround.",tab:"e|----------------------------7--8--7--|\nB|----------------------5--7--8---------|\nG|--------------0--2--4--5--------------|\nD|--------0--2--3-----------------------|\nA|--0--3--5-----------------------------|\nE|---------------------------------------|",key:"G",difficulty:"intermediate",artists:["Don Rich","Redd Volkaert","Albert Lee"],tips:["Pica alternada estricta; el roll ha de sonar encadenat, no amb notes marcades.","El G(0), A(2), B(3), C(3), D(5), E(4/5) — els graus naturals de G major en pujada.","Pratca el G-Run avall (l'altre lick) i aquest pujant per dominar el turnaround complet."]},{id:"honky-tonk-turnaround",name:"Honky-Tonk Turnaround",category:"double-stop",description:"El turnaround honky-tonk per excel\xb7l\xe8ncia: dobles parades en terceres i sisenes que cauen cap a la t\xf2nica amb swing. Cada parella sona la tercera o sisena del grau, creant la tensi\xf3 que torna a l'acord inicial, el cor del country cl\xe0ssic.",tab:"e|-----------10--8--------------|\nB|--------8-----10--8-----------|\nG|-----7-----------10--9-------|\nD|--10------------------10--7--|\nA|-----------------------------|\nE|-----------------------------|",key:"C",difficulty:"intermediate",artists:["Chet Atkins","Merle Travis","James Burton"],tips:["Les dobles parades amb swing llarga-curta; la tensi\xf3 ve de la sisena (E-B) que resolt avall a la tercera.","Cada parella \xe9s tercera i quinta d'un grau: C (D10/G7), G (D9/G7), C alt (E10/G7).","Mant\xe9n la mateixa digitaci\xf3 de doble parada en baixar perqu\xe8 el turnaround flu\xefxi sense reiniciar."]},{id:"western-swing-lick",name:"Western Swing Lick",category:"hybrid-picking",description:"Lick de western swing amb arpegis h\xedbrids que salten octaves amb pua i dits, elegant i ballable. Cada salt aprofita la pua per les greus i els dits per les agudes, perqu\xe8 el swing flueixi sense moure la m\xe0.",tab:"e|---------------12----------12-------------------8--|\nB|--------10------------8-10------------8-10-------10--|\nG|-----10------10-----9-------12----10------10---9-----|\nD|--12--------------------------------------------------|\nA|------------------------------------12---------------|\nE|---------------------8--------------------------------|",key:"G",difficulty:"expert",artists:["Redd Volkaert","Albert Lee","Danny Gatton"],tips:['Pua per D(12) i A(10/8), dits per les agudes; els salts d\'octava surten canviant de "t\xe8cnica" no de m\xe0.',"\xc9s un arpegi de G amb la s\xe8tima (F#) que fa passar la melodia entre registres.","Pratca els arpegis per separat (G, D, G a l'octava) abans de lligar-los en el swing."]},{id:"country-blues-bend",name:"Country Blues Bend",category:"bend",description:'Bend de blues amb resoluci\xf3 country: puja a la tercera menor (G) i es resol avall a la segona, amb el vibrato vocal de Danny Gatton. La nota "girant" sobre la progressi\xf3 de E crea la tensi\xf3 bluesy que el country ha agafat prestada.',tab:"e|--7b9-7b9--7r--9b11-9-9b11-9--9b11-9-----------|\nB|---------------------------------------------------|\nG|---------------------------------------------------|\nD|---------------------------------------------------|\nA|---------------------------------------------------|\nE|---------------------------------------------------|",key:"E",difficulty:"intermediate",artists:["Danny Gatton","Albert Lee","Redd Volkaert"],tips:["El bend a la tercera menor de E (G, 7b9) \xe9s el so blues; la resoluci\xf3 avall a la segona (F#, 7) \xe9s el gest country.","Puja lent, vibra al cim i resol controladament; la velocitat de la resoluci\xf3 fa el car\xe0cter.","Comprova els bends contra les notes reals (cordes B/E) perqu\xe8 quedin afinats."]}]}}]);